class Solution {
public:
    int nonAdjacent(vector<int>& nums) {
        int n = nums.size();

        if (n == 1) {
            return nums[0];
        }

        vector<int> dp(n);

        dp[0] = nums[0];
        dp[1] = max(nums[0], nums[1]);

        for (int i = 2; i < n; i++) {
          /* here either we have two cases in max as dp[i-1] means not picking that particular element and picking the element beside it 
          and the case is nums[i]+dp[i-2] means picking that ith element and picking its alternative element because we should not pick adjacent elements*/
            dp[i] = max(dp[i - 1], nums[i] + dp[i - 2]);
        }

        return dp[n - 1];
    }
};

