class Solution {
    public int nonAdjacent(int[] nums) {
        int yesterday = Math.max(nums[0], nums[1]);
        int dayBeforeYesterday = nums[0];
        for(int i=2; i<nums.length; i++){
            int pick = nums[i] + dayBeforeYesterday;
            int notPick = yesterday;
            int today = Math.max(pick, notPick);
            dayBeforeYesterday=yesterday;
            yesterday=today;
        }
        return yesterday;
    }
}
